let currentCategory = 'all';
let currentPhotoIndex = 0;
let currentDocId = null;

function selectCategory(cat, btn) {
  currentCategory = cat;
  document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) {
    btn.classList.add('active');
  } else {
    const targetBtn = document.querySelector(`.filter-btn[data-cat="${cat}"]`);
    if (targetBtn) targetBtn.classList.add('active');
  }
  applyFilters();
}

function filterAcervo() {
  applyFilters();
}

function applyFilters() {
  const input = document.getElementById('acervoSearchInput');
  const query = (input ? input.value : '').trim().toLowerCase();

  let anyVisibleSection = false;
  document.querySelectorAll('.category-section').forEach(section => {
    const secCat = section.getAttribute('data-cat');
    const matchesCat = (currentCategory === 'all' || currentCategory === secCat);

    if (!matchesCat) {
      section.classList.add('hidden-by-filter');
      return;
    }

    let visibleItemsInSection = 0;
    section.querySelectorAll('.searchable-item').forEach(item => {
      const hay = (item.getAttribute('data-search') || '').toLowerCase();
      const hit = !query || hay.includes(query);
      item.classList.toggle('hidden-by-search', !hit);
      if (hit) visibleItemsInSection++;
    });

    if (visibleItemsInSection === 0 && query) {
      section.classList.add('hidden-by-filter');
    } else {
      section.classList.remove('hidden-by-filter');
      anyVisibleSection = true;
    }
  });

  const emptyEl = document.getElementById('acervoEmptyState');
  if (emptyEl) {
    emptyEl.style.display = anyVisibleSection ? 'none' : 'block';
  }
}

function openReader(docId, preferMode) {
  const data = ACERVO_READER_DATA[docId];
  if (!data) return;
  currentDocId = docId;

  const modal = document.getElementById('appDocModal');
  const titleEl = document.getElementById('docModalTitle');
  const subEl = document.getElementById('docModalSubtitle');
  const openBtn = document.getElementById('docModalOpenLink');
  const toggleBtn = document.getElementById('docModalToggleMode');
  const bodyEl = document.getElementById('docModalBody');

  titleEl.innerText = data.title;
  subEl.innerText = data.subtitle;
  openBtn.href = data.href;

  const mode = preferMode || data.mode;
  bodyEl.classList.remove('iframe-mode');

  if (mode === 'iframe') {
    bodyEl.classList.add('iframe-mode');
    bodyEl.innerHTML = `<iframe class="doc-modal-iframe" src="${data.href}" title="${data.title}"></iframe>`;
    if (data.body) {
      toggleBtn.style.display = 'inline-flex';
      toggleBtn.innerText = '📖 Ver Texto Extraído';
      toggleBtn.onclick = () => openReader(docId, 'text');
    } else {
      toggleBtn.style.display = 'none';
    }
  } else if (mode === 'pdf') {
    bodyEl.innerHTML = (
      '<div class="reader-info-note"><strong>Modo de Leitura Móvel/Offline:</strong> Texto extraído automaticamente do PDF para leitura rápida em qualquer celular. ' +
      'Em computadores e aparelhos compatíveis, você também pode clicar em <em>"🖼️ Tentar Visualizador PDF"</em> ou <em>"↗️ Abrir Original"</em>.</div>' +
      data.body
    );
    toggleBtn.style.display = 'inline-flex';
    toggleBtn.innerText = '🖼️ Tentar Visualizador PDF';
    toggleBtn.onclick = () => openReader(docId, 'iframe');
  } else if (mode === 'text') {
    bodyEl.innerHTML = data.body;
    toggleBtn.style.display = 'inline-flex';
    toggleBtn.innerText = '🖼️ Visualizador Original';
    toggleBtn.onclick = () => openReader(docId, 'iframe');
  } else {
    bodyEl.innerHTML = data.body;
    toggleBtn.style.display = 'none';
  }

  bodyEl.scrollTop = 0;
  modal.classList.add('open');
  document.body.style.overflow = 'hidden';
}

function openFrameModal(docId) {
  openReader(docId, 'iframe');
}

function closeDocModal() {
  const modal = document.getElementById('appDocModal');
  const bodyEl = document.getElementById('docModalBody');
  if (modal) modal.classList.remove('open');
  if (bodyEl) bodyEl.innerHTML = '';
  document.body.style.overflow = '';
}

function openPhotoModal(idx) {
  currentPhotoIndex = idx;
  renderPhotoModal();
  const modal = document.getElementById('photoLightboxModal');
  modal.classList.add('open');
  document.body.style.overflow = 'hidden';
}

function stepPhotoModal(delta) {
  const total = ACERVO_PHOTOS_DATA.length;
  currentPhotoIndex = (currentPhotoIndex + delta + total) % total;
  renderPhotoModal();
}

function renderPhotoModal() {
  const ph = ACERVO_PHOTOS_DATA[currentPhotoIndex];
  if (!ph) return;
  document.getElementById('photoModalCounter').innerText = `${currentPhotoIndex + 1} / ${ACERVO_PHOTOS_DATA.length}`;
  document.getElementById('photoModalTitle').innerText = ph.title;
  document.getElementById('photoModalImg').src = ph.src;
  document.getElementById('photoModalImg').alt = ph.title;
  document.getElementById('photoModalCaption').innerText = ph.caption;
  document.getElementById('photoModalOpenLink').href = ph.src;
}

function closePhotoModal() {
  const modal = document.getElementById('photoLightboxModal');
  if (modal) modal.classList.remove('open');
  document.body.style.overflow = '';
}

function handleHashRoute() {
  const h = window.location.hash;
  if (!h) return;
  const map = {
    '#cat-fecit': 'fecit',
    '#cat-artigos': 'artigos',
    '#cat-planejamentos': 'planejamentos',
    '#cat-atividades': 'atividades',
    '#cat-evidencias': 'evidencias'
  };
  if (map[h]) {
    selectCategory(map[h]);
  }
}

document.addEventListener('keydown', (e) => {
  const photoOpen = document.getElementById('photoLightboxModal').classList.contains('open');
  const docOpen = document.getElementById('appDocModal').classList.contains('open');
  if (e.key === 'Escape') {
    if (photoOpen) closePhotoModal();
    if (docOpen) closeDocModal();
  } else if (photoOpen && e.key === 'ArrowRight') {
    stepPhotoModal(1);
  } else if (photoOpen && e.key === 'ArrowLeft') {
    stepPhotoModal(-1);
  }
});

window.addEventListener('hashchange', handleHashRoute);
window.addEventListener('DOMContentLoaded', () => {
  handleHashRoute();
});
